import app from 'flarum/admin/app';
import apiCall from '../../common/utils/apiCall';
import verificationPrompt from '../../common/utils/verificationPrompt';
export const APPROVED_PAGE_SIZE = 15;
const SEARCH_DEBOUNCE_MS = 250;
const trans = key => app.translator.trans(`ramon-verified.admin.requests.${key}`);
// As linhas são um agregado sem model próprio, então não passam pelo store:
// o payload só segue o envelope JSON:API.
export default class ApprovedUsersState {
  loading = false;
  rows = [];
  total = 0;
  offset = 0;
  query = '';
  // Vazio significa sem filtro.
  tierFilter = '';
  tiers = [];
  busy = {};
  _searchTimer = null;
  // Uma resposta mais antiga e mais lenta não pode sobrescrever a atual.
  _loadSeq = 0;
  async load() {
    const seq = ++this._loadSeq;
    this.loading = true;
    m.redraw();
    const params = {
      q: this.query,
      offset: this.offset,
      limit: APPROVED_PAGE_SIZE
    };
    if (this.tierFilter) params.tier = this.tierFilter;
    const res = await apiCall({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/verified/approved-users',
      params
    }, {
      errorKey: 'ramon-verified.admin.requests.load_approved_failed'
    });
    if (seq !== this._loadSeq) return;
    this.loading = false;
    if (res) {
      this.rows = (res.data || []).map(resource => ({
        id: resource.id,
        ...resource.attributes
      }));
      this.total = res.meta && res.meta.total || 0;
      if (res.meta && res.meta.tiers) this.tiers = res.meta.tiers;
    }
    m.redraw();
  }
  setSearch(value) {
    this.query = value;
    this.offset = 0;
    if (this._searchTimer) clearTimeout(this._searchTimer);
    this._searchTimer = setTimeout(() => this.load(), SEARCH_DEBOUNCE_MS);
    m.redraw();
  }
  goToPage(offset) {
    this.offset = Math.max(0, offset);
    this.load();
  }
  setTierFilter(tierId) {
    if (this.tierFilter === tierId) return;
    this.tierFilter = tierId;
    this.offset = 0;
    this.load();
  }
  findTier(tierId) {
    if (!tierId) return null;
    return this.tiers.find(t => t.id === tierId) || null;
  }

  // Quem chama também recarrega os pedidos: o pedido correspondente muda de status.
  async revokeUser(row) {
    const result = await verificationPrompt({
      title: trans('revoke_button'),
      noteLabel: trans('revoke_prompt'),
      confirmLabel: trans('revoke_button'),
      withTier: false
    });
    if (!result) return false;
    const key = 'user-' + row.id;
    this.busy[key] = true;
    m.redraw();
    const res = await apiCall({
      method: 'DELETE',
      url: app.forum.attribute('apiUrl') + '/verified/users/' + row.id + '/verify',
      body: {
        adminNote: result.note
      }
    }, {
      errorKey: 'ramon-verified.admin.requests.revoke_user_failed'
    });
    delete this.busy[key];
    if (res !== null) {
      app.alerts.show({
        type: 'success'
      }, trans('revoke_success'));
      this.load();
      m.redraw();
      return true;
    }
    m.redraw();
    return false;
  }
}
flarum.reg.add('ramon-verified', 'admin/states/ApprovedUsersState', ApprovedUsersState);